import{_ as r,r as a,o as l,c as o,e as n,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const k=JSON.parse('{"title":"Introduction - October CMS - 3.x","titleTemplate":false,"description":"Tailor website content to your exact requirements.","frontmatter":{"subtitle":"Tailor website content to your exact requirements."},"headers":[{"level":2,"title":"Directory Structure","slug":"directory-structure","link":"#directory-structure","children":[{"level":3,"title":"App Blueprints","slug":"app-blueprints","link":"#app-blueprints","children":[]},{"level":3,"title":"Theme Blueprints","slug":"theme-blueprints","link":"#theme-blueprints","children":[]}]},{"level":2,"title":"Blueprint Types","slug":"blueprint-types","link":"#blueprint-types","children":[]},{"level":2,"title":"Blueprint Structure","slug":"blueprint-structure","link":"#blueprint-structure","children":[]},{"level":2,"title":"Integration with Multisite","slug":"integration-with-multisite","link":"#integration-with-multisite","children":[]},{"level":2,"title":"Migrating Blueprints","slug":"migrating-blueprints","link":"#migrating-blueprints","children":[{"level":3,"title":"Refreshing Content","slug":"refreshing-content","link":"#refreshing-content","children":[]},{"level":3,"title":"Propagating Content","slug":"propagating-content","link":"#propagating-content","children":[]},{"level":3,"title":"Pruning Content","slug":"pruning-content","link":"#pruning-content","children":[]}]}],"relativePath":"3.x/cms/tailor/introduction.md","filePath":"3.x/cms/tailor/introduction.md"}'),u={name:"3.x/cms/tailor/introduction.md"};function d(h,e,g,m,b,y){const t=a("pre-heading"),s=a("post-heading"),i=a("VideoBlockLink");return l(),o("div",null,[n(t),e[0]||(e[0]=p("h1",null,"Introduction",-1)),n(s),n(i,{src:"https://www.youtube.com/watch?v=_WMH4mlMdjk",title:"Tailor Tutorial",description:"This video describes how to quickly create a complete blog solution with Tailor.",prompt:"Watch the tutorial"}),e[1]||(e[1]=c(`<p>Tailor is a feature that defines file-based content structures used by your website, such as a company blog or team page. Tailor automatically generates a backend user interface for managing records and provides CMS Components for displaying and linking records on the frontend.</p><p>When using Tailor you can skip the traditional plugin development workflow and go straight to defining content. Fields are defined simply as blueprint templates and content is stored in special database tables. The blueprint template can also specify navigation and other modifiers.</p><h2 id="directory-structure"><a href="#directory-structure" class="header-anchor">#</a> Directory Structure</h2><p>Blueprints are YAML files that reside in the <strong>app/blueprints</strong> directory by default, in addition to the <strong>themes/.../blueprints</strong> directory for a <a href="./../themes/themes.html">CMS theme</a>. Where to place your blueprints depends on the context: <strong>App Blueprints</strong> are globally available, whereas <strong>Theme Blueprints</strong> are only available when that theme is selected.</p><h3 id="app-blueprints"><a href="#app-blueprints" class="header-anchor">#</a> App Blueprints</h3><p>Below you can see an example blueprint directory structure. Each blueprint can reside in any directory and any file name can be used. Blueprints can be organised in subdirectories of any nesting depth.</p><pre class="dir-container"><code><p>├── app
|   └── <code>blueprints</code>  <em>← Blueprints Start Here</em>
|       ├── blog
|       │   └── blog.yaml
|       │   └── author.yaml
|       ├── about
|       │   └── about.yaml
|       ├── wiki
|       │   └── article.yaml</p>
</code></pre><h3 id="theme-blueprints"><a href="#theme-blueprints" class="header-anchor">#</a> Theme Blueprints</h3><p>Next is an example of a blueprint structure inside the <strong>demo</strong> theme. Just like in the app directory, blueprints can reside in any directory with any filename, with any nesting depth. The admin panel navigation for these blueprints will only appear when the theme is selected, often controlled by the <a href="./../resources/multisite.html">multisite settings</a>.</p><pre class="dir-container"><code><p>├── themes
|   └── demo
|       ├── <code>blueprints</code>  <em>← Blueprints Start Here</em>
|       │   └── settings.yaml
|       │   └── color-scheme.yaml</p>
</code></pre><h2 id="blueprint-types"><a href="#blueprint-types" class="header-anchor">#</a> Blueprint Types</h2><p>The blueprint <strong>type</strong> property determines how the blueprint should be implemented. There are several types available and most blueprints will specify <a href="./../../element/form-fields.html">form field definitions</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Entry</td><td>the standard content structure that supports drafts.</td></tr><tr><td>Global</td><td>a single record in the database and is often used for settings and configuration.</td></tr><tr><td>Mixin</td><td>defines reusable field definitions that can be imported and mixed in with other field definitions.</td></tr></tbody></table></div><p>Each blueprint type is described in more detail in the <a href="./blueprints.html">Blueprints article</a>.</p><h2 id="blueprint-structure"><a href="#blueprint-structure" class="header-anchor">#</a> Blueprint Structure</h2><div class="custom-block aside"><p>Blueprints are 100% portable. They use internal identifiers and can reside in any directory with any file name.</p></div><p>Blueprints are defined using the YAML syntax and will always contain three identifiers, a unique UUID, a user-friendly handle and the blueprint type. The filename and folder of a blueprint is used to organize blueprints and is not used as an identifier. All other properties are defined in the blueprint&#39;s relevant documentation article.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">uuid</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
<span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token key atrule">name</span><span class="token punctuation">:</span> Post

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token comment"># [...]</span>
</code></pre></div><p>The blueprint <strong>handle</strong> is a human-readable approach to referencing a blueprint object. Using the above blueprint as a reference, we can reference the entries using the handle.</p><div class="custom-block tip"><p>Handles follow a similar naming convention to PHP namespaces and can be organised with the backslash <code>\\</code> separator.</p></div><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">section blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><p>The blueprint <strong>uuid</strong> is a unique identifier used when blueprints reference other blueprints. For example, when a field references a mixin. When first creating a blueprint, you can choose to not include a UUID and one will be magically created for you on the first migration.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">_blog_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">source</span><span class="token punctuation">:</span> edcd102e<span class="token punctuation">-</span>0525<span class="token punctuation">-</span>4e4d<span class="token punctuation">-</span>b07e<span class="token punctuation">-</span>633ae6c18db6
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mixin
</code></pre></div><h2 id="integration-with-multisite"><a href="#integration-with-multisite" class="header-anchor">#</a> Integration with Multisite</h2><p>Blueprints do not use <a href="./../resources/multisite.html">multisite capabilities</a> by default. You may use the <code>multisite</code> property to enable this. When enabled, records can be unique to each configured site.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">handle</span><span class="token punctuation">:</span> Blog\\Post
<span class="token key atrule">type</span><span class="token punctuation">:</span> entry
<span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>When multisite is enabled, all fields in the blueprint become translatable. To keep the same value for a field, set the <code>translatable</code> property to false. In this example, when saving the record the <strong>name</strong> field will be copied to every site when it is saved.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ...</span>
<span class="token key atrule">multisite</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
        <span class="token key atrule">translatable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>You may also set the value to <strong>sync</strong> to keep the records synchronized across sites, which is helpful for categories and tags. When using sync, each record will always exist on every site, although the content can be different.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> sync
</code></pre></div><p>When using <a href="./../resources/multisite.html">Site Groups</a>, the records will be propagated to all sites within that group. This can be changed by setting the <code>multisite</code> property to <strong>all</strong> to sync within all sites.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> all
</code></pre></div><p>Setting to <strong>locale</strong> will sync the records to all sites that share the same locale.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">multisite</span><span class="token punctuation">:</span> locale
</code></pre></div><h2 id="migrating-blueprints"><a href="#migrating-blueprints" class="header-anchor">#</a> Migrating Blueprints</h2><p>Blueprints and their structure are migrated in the database during the normal database migration process. When a change is made manually to a blueprint file, you should run the <code>tailor:migrate</code> command to update the database tables.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:migrate
</code></pre></div><div class="custom-block tip"><p>Blueprints are cached when debug mode is turned off. The migration command can also be used to clear the blueprint cache.</p></div><h3 id="refreshing-content"><a href="#refreshing-content" class="header-anchor">#</a> Refreshing Content</h3><p>You may delete all the content managed by Tailor using the <code>tailor:refresh</code> command.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:refresh
</code></pre></div><p>To refresh a single blueprint use the <code>--blueprint</code> option and specify its handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:refresh <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Post&quot;</span>
</code></pre></div><h3 id="propagating-content"><a href="#propagating-content" class="header-anchor">#</a> Propagating Content</h3><p>When using the <strong>sync</strong> option for multisite, you may retroactively propagate records using the <code>tailor:propagate</code> command.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate
</code></pre></div><p>To propagate a single blueprint use the <code>--blueprint</code> option and specify its handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:propagate <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Category&quot;</span>
</code></pre></div><h3 id="pruning-content"><a href="#pruning-content" class="header-anchor">#</a> Pruning Content</h3><p>As a general rule Tailor will never drop table columns and delete content. If a field is removed, the column will be renamed instead of dropped. For example, an old field named <code>content</code> may appear as <code>x_content_fb418fac</code> in the database table. Tables for old blueprints are also kept in case they are ever restored.</p><p>You may prune unused database columns with the <code>tailor:prune</code> command. This command will also drop tables that no longer have an associated blueprint.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune
</code></pre></div><p>You may only prune fields using the <code>--fields</code> modifier. To only prune tables, use the <code>--tables</code> modifier.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune <span class="token parameter variable">--fields</span>
php artisan tailor:prune <span class="token parameter variable">--tables</span>
</code></pre></div><p>To prune a single blueprint use the <code>--blueprint</code> option and specify its handle.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan tailor:prune <span class="token parameter variable">--blueprint</span><span class="token operator">=</span><span class="token string">&quot;Blog\\Post&quot;</span>
</code></pre></div>`,56))])}const v=r(u,[["render",d]]);export{k as __pageData,v as default};
